<script setup lang="ts">import type{WebhookDelivery}from"~/types/webhook";defineProps<{open:boolean;deliveries:WebhookDelivery[]}>();defineEmits<{close:[]}>();const{tr,formatDate}=useAppPreferences();</script>
<template><AppModal :open="open" :title="tr('تاریخچه تحویل','Delivery history')" @close="$emit('close')"><UiEmptyState v-if="!deliveries.length" :title="tr('هنوز ارسالی ثبت نشده است.','No deliveries yet.')"/><div v-for="delivery in deliveries" v-else :key="delivery.id" class="mb-3 rounded-xl border p-3 text-xs"><div class="flex justify-between"><b>{{delivery.event}}</b><span :class="delivery.httpStatus&&delivery.httpStatus>=200&&delivery.httpStatus<300?'text-emerald-600':'text-red-500'">HTTP {{delivery.httpStatus||'—'}}</span></div><p class="mt-2 text-slate-400">{{delivery.durationMs??'—'}}ms · {{formatDate(delivery.createdAt,{dateStyle:'medium',timeStyle:'short'})}}</p><pre class="mt-2 max-h-24 overflow-auto rounded bg-slate-950 p-2 text-left text-slate-200" dir="ltr">{{delivery.responseBody||'—'}}</pre></div></AppModal></template>
